calculation.expression:
v.index = v.index + 1;
v.angle = v.index * 360 / v.count;
t.lightx = 0;
t.lightz = 0;
t.lightx = math.cos(v.angle) * v.radius;
t.lightz = math.sin(v.angle) * v.radius;
t.lighty = -120;

v.normalized = math.sqrt(t.lightx * t.lightx + t.lightz * t.lightz + t.lighty * t.lighty);
t.lightrx = 0;
t.lightry = 0;
t.lightrz = 0;
t.lightrx = t.lightx / v.normalized;
t.lightry = t.lighty / v.normalized;
t.lightrz = t.lightz / v.normalized;

particle_effect.pre_effect_expression:
variable.posx = t.lightx;
variable.posy = t.lighty;
variable.posz = t.lightz;
variable.rotx = t.lightrx;
variable.roty = t.lightry;
variable.rotz = t.lightrz;
